    async function generateAllVoices() {
        if (!state.currentProject) return;
        if (!confirm('Generate dialogue for EVERY shot that has any?\n\n'
            + 'This SPENDS on each line, and registers each take against its shot. '
            + 'Cast your characters first, or uncast ones will speak in the provider default voice.')) return;
        setStatus('Generating all dialogue…');
        try {
            const res = await api(`/projects/${state.currentProject.id}/voice/batch`,
                { method: 'POST', body: '{}' });
            setStatus(`Dialogue: ${res.generated || res.total || 0} line(s).`);
        } catch (err) { setStatus('Batch failed: ' + err.message); }
    }

    async function createSequence() {
        if (!state.currentProject) return;
        if (!SEQ.picked.length) return setStatus('Pick the shots the move travels through first.');
        const name = (document.getElementById('sequenceName') || {}).value || '';
        const description = (document.getElementById('sequenceDescription') || {}).value || '';
        try {
            await api(`/projects/${state.currentProject.id}/sequences`, {
                method: 'POST',
                body: JSON.stringify({ name, description, shot_ids: SEQ.picked }),
            });
            SEQ.picked = [];
            const n = document.getElementById('sequenceName'); if (n) n.value = '';
            const d = document.getElementById('sequenceDescription'); if (d) d.value = '';
            setStatus('Sequence created. Preview it before generating — the preview is free.');
            loadSequences();
            renderSequencePicker(state.videoShots || [], state.videoAssetsByShot || {});
        } catch (err) { setStatus('Could not create the sequence: ' + err.message); }
    }

    function generateAllVideos() {
        /*
         * A paid action states its cost before it spends. Six of these were
         * silent, which is why a director generated elsewhere rather than
         * risk credits on something they could not see.
         */
        if (!state.currentProject) return;
        /*
         * A batch sends a DIFFERENT prompt per shot, so no single one is the
         * truth about what is bought. One is shown as a REPRESENTATIVE and
         * labelled as one: unlabelled it would imply the batch sends that text,
         * and with none the largest spend in the app is approved on a count.
         */
        return (async () => {
            let sample = null;
            const first = (state.shots || []).find(sh => sh.has_keyframe || sh.image_url)
                || (state.shots || [])[0];
            if (first) {
                try { sample = await api(`/shots/${first.id}/video/preview`); } catch (_) { sample = null; }
            }
            if (!confirm(`Generate video for EVERY shot that has a keyframe?\n\n`
                + 'This is one paid generation per shot and is the largest single spend in the app. '
                + 'Generate one shot first to check the look before buying the whole board.'
                + (sample && sample.prompt
                    ? `\n\nEach shot sends its own prompt. ${first.shot_code || 'The first'} would send:\n\n`
                      + String(sample.prompt).slice(0, 400)
                    : ''))) return;
            return generateAllVideosRun();
        })();
    }

    function generateAllVideosRun() {
        if (!state.currentProject) return;
        const prog = document.getElementById('videoshotsProgress');
        const bar = document.getElementById('videoshotsProgressBar');
        const lbl = document.getElementById('videoshotsProgressLabel');
        prog.style.display = 'block';
        bar.style.width = '0%';
        lbl.textContent = 'Starting video generation...';
        let total = 1, done = 0;

        streamSSEPost(
            '/projects/' + state.currentProject.id + '/video/batch/stream',
            {},
            (ev) => {
                if (ev.type === 'status' && ev.total_shots) { total = ev.total_shots || 1; }
                else if (ev.type === 'shot_start') { lbl.textContent = 'Generating ' + (ev.shot_code || ev.shot_id || '...'); }
                else if (ev.type === 'shot_complete' || ev.type === 'shot_failed') {
                    done++;
                    bar.style.width = Math.round((done / total) * 100) + '%';
                    lbl.textContent = done + '/' + total + ' processed';
                }
            },
            () => {
                lbl.textContent = 'Done';
                setStatus('Video batch complete');
                setTimeout(() => { prog.style.display = 'none'; }, 1500);
                loadVideoShots();
            },
            (err) => { setStatus('Error: ' + (err ? err.message : 'stream failed')); prog.style.display = 'none'; }
        );
    }
